# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Timekeeping relay test hooks" do
  # Anyone able to pause the relay could stop every company's entries from
  # reaching the monolith, so the hook takes the same service token as the
  # other internal routes.
  it "refuses the relay pause and resume hooks without the service token" do
    service_token = "service-#{SecureRandom.hex(24)}"
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => service_token
    ) do
      user_token = mint_token({ sub: 7, company_id: 1, role: "owner" })

      post "/internal/v1/test-hooks/relay/pause"
      expect([response.status, response.parsed_body]).to eq([401, { "reason" => "unauthorized" }])

      post "/internal/v1/test-hooks/relay/pause", headers: { "Authorization" => "Bearer #{user_token}" }
      expect([response.status, response.parsed_body]).to eq([401, { "reason" => "unauthorized" }])

      post "/internal/v1/test-hooks/relay/resume", headers: { "Authorization" => "Bearer #{service_token}x" }
      expect([response.status, response.parsed_body]).to eq([401, { "reason" => "unauthorized" }])
    end
  end
end
